package dev.exodus.teleporter.block;
import dev.exodus.MatchManager;import dev.exodus.teleporter.blockentity.ExodusTeleporterBlockEntity;import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.BlockEntity;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.BooleanProperty;import net.minecraft.world.level.material.PushReaction;import net.minecraft.world.phys.BlockHitResult;import net.minecraftforge.network.NetworkHooks;
public final class ExodusTeleporterBlock extends BaseEntityBlock {public static final BooleanProperty ACTIVE=BooleanProperty.create("active");public ExodusTeleporterBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(ACTIVE,false));}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(ACTIVE);}@Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new ExodusTeleporterBlockEntity(pos,state);}@Override public RenderShape getRenderShape(BlockState state){return RenderShape.MODEL;}@Override public PushReaction getPistonPushReaction(BlockState state){return PushReaction.BLOCK;}@Override public <T extends BlockEntity> net.minecraft.world.level.block.entity.BlockEntityTicker<T> getTicker(Level level,BlockState state,net.minecraft.world.level.block.entity.BlockEntityType<T> type){return level instanceof ServerLevel&&type==dev.exodus.teleporter.ExodusTeleporterRegistry.TELEPORTER_ENTITY.get()?(l,p,s,b)->ExodusTeleporterBlockEntity.tick((ServerLevel)l,p,s,(ExodusTeleporterBlockEntity)b):null;}@Override public InteractionResult use(BlockState state,Level level,BlockPos pos,Player player,InteractionHand hand,BlockHitResult hit){if(level.isClientSide)return InteractionResult.SUCCESS;if(!(player instanceof ServerPlayer sp)||!MatchManager.isActiveMatchPlayer(sp)){player.sendSystemMessage(net.minecraft.network.chat.Component.literal("Teleporter is inactive."));return InteractionResult.FAIL;}if(level.getBlockEntity(pos) instanceof ExodusTeleporterBlockEntity be){java.util.UUID current=dev.exodus.ExodusSavedData.get(sp.server).matchId;if(be.matchId()!=null&&!be.matchId().equals(current))be.reset();if(be.matchId()==null)be.matchId(current);NetworkHooks.openScreen(sp,be,pos);return InteractionResult.CONSUME;}return InteractionResult.FAIL;}}
